# Chaque écran : js (état), scroll (élément à placer vers le haut de l'écran), targets (nom -> sélecteur ou js:expression).
SPACE_T = "state.profile=Object.assign({},state.accounts[0]);state.view='transitaire';state.showRoleMenu=false;state.showTransitForm=false;state.showTransitFinished=false;state.externalParcels=[DEMO_PARCELS.annonce,DEMO_PARCELS.domicile];render();window.scrollTo(0,0);"
FORM = "state.profile=Object.assign({},state.accounts[0]);state.view='transitaire';state.showTransitForm=true;state.transitDraft=Object.assign(emptyTransitDraft(),%s);render();"
POLE = "state.profile=Object.assign({},state.accounts[0]);state.view='agentsourcing';state.showRoleMenu=false;state.detailAgentOrderId=null;state.orders=[%s];render();window.scrollTo(0,0);"
def form(d): return FORM % d
def pole(o, extra=""): return POLE % o + extra

